def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

def check_n5(x):
    lhs = x**5 + x
    rhs_minus_2 = lhs - 2

    if is_power_of_two(rhs_minus_2):
        import math
        k = int(math.log2(rhs_minus_2))
        return x, k
    return None

odd_xs = [7, 9, 11, 13, 15]
results = {}
for x in odd_xs:
    result = check_n5(x)
    if result:
        results[x] = result
    else:
        results[x] = "No solution found"

print(results)
